package localchat;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
/** Exact job evidence recovers a known path typo; access checks, provenance and original files are preserved. */
public final class PdfResultPathTest {
    static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
    static Tools tools(Path root,boolean auto,AtomicInteger asks){return new Tools(new Tools.Context(root,root.resolve("skills"),root.resolve("rules.md"),root.resolve("settings.properties"),Map.of(),null,new Mcp(),PathMap.none(),auto,EnumSet.noneOf(Tools.Access.class),(a,b)->{asks.incrementAndGet();return Tools.Decision.NO;}),List.of());}
    static Tools.Result read(Tools tool,Path path){return tool.execute(new ChatClient.ToolCall("read","read_file",Json.obj("path",path.toString())));}
    public static void main(String[] args)throws Exception{
        Path root=Files.createTempDirectory("localchat-result-path-"),run=Files.createDirectories(root.resolve("123456/Controle/Octop-PDFCONTROL/"+"a".repeat(32))),correct=run.resolve("engine/checked/resultaten.json"),wrong=run.resolve("checked/resultaten.json"),job=run.resolve("job.json");Files.createDirectories(correct.getParent());Files.writeString(correct,"{\"verified\":true}");
        var record=Json.obj("job_id","a".repeat(32),"status","done","results",correct.toString());Files.writeString(job,Json.write(record));var asks=new AtomicInteger();var tool=tools(root,false,asks);
        try{for(String language:I18n.CODES){I18n.setLanguage(language);var hint=read(tool,wrong);check(!hint.isError&&hint.text.contains(correct.toString())&&hint.text.contains(wrong.toString())&&hint.text.contains("job.json"),"all languages report successful confirmed recovery and both paths");check(hint.text.contains("verified"),"recovered call returns actual file contents, not a hidden error");check(!Files.exists(wrong),"no fabricated alias or directory created");}
            try(var server=new FeatureTest.Server(FeatureTest.json(AttachmentTest.toolReply(wrong)),FeatureTest.json(FeatureTest.answer("Confirmed result read",30,5)))){
                var calls=new AtomicInteger();new Agent(tool).run(Provider.CUSTOM,server.url(),"","fixture","fixture","Read confirmed result",List.of(ChatClient.Message.user("Read the existing check results, do not rerun checking")),false,new Agent.Ui(){public void text(String text){}public void step(){}public void toolStarted(ChatClient.ToolCall call){calls.incrementAndGet();}public void toolFinished(ChatClient.ToolCall call,Tools.Result result){check(!result.isError&&result.text.contains("verified"),"agent receives successful data for the single corrected read");}});
                check(calls.get()==1&&server.requests.size()==2,"one tool read then final answer; no extra model request for repairing the path");check(Json.write(server.requests.get(1)).contains("verified")&&Json.write(server.requests.get(1)).contains("job.json"),"next inference receives data and correction provenance");
            }
            check(!read(tool.readOnly(true),wrong).isError,"read-only profile permits verified read recovery");
            check(asks.get()==0,"workspace diagnostic needs no external access");check(read(tool,correct).text.contains("verified"),"explicit corrected read succeeds normally");
            for(String status:List.of("running","failed","cancelled")){record.put("status",status);Files.writeString(job,Json.write(record));check(!read(tool,wrong).text.contains(correct.toString()),"no completed evidence claimed for "+status);}
            record.put("status","done");record.put("results",root.resolve("another.json").toString());Files.writeString(job,Json.write(record));check(!read(tool,wrong).text.contains(correct.toString()),"wrong manifest path is not trusted");
            record.put("results",correct.toString());record.put("job_id","b".repeat(32));Files.writeString(job,Json.write(record));check(!read(tool,wrong).text.contains(correct.toString()),"other job evidence rejected");
            record.put("job_id","a".repeat(32));Files.writeString(job,Json.write(record));Path outside=Files.createDirectories(root.resolve("selected-workspace"));var restricted=tools(outside,false,asks);var denied=read(restricted,wrong);check(denied.isError&&!denied.text.contains(correct.toString())&&asks.get()==1,"outside-workspace denial never discloses alternative path");
            var explicit=tools(outside,false,asks).attachments(List.of(wrong.toString()));check(!read(explicit,wrong).text.contains(correct.toString()),"a single attached wrong file grants no sibling evidence access");
            // An existing requested file is always read as requested; never substitute another result.
            Files.createDirectories(wrong.getParent());Files.writeString(wrong,"EXISTING-EXACT-FILE");check(read(tool,wrong).text.contains("EXISTING-EXACT-FILE")&&!read(tool,wrong).text.contains("verified"),"existing paths are not redirected");Files.delete(wrong);
            Files.writeString(correct,"line one\nline two\nline three\nline four");var paged=tool.execute(new ChatClient.ToolCall("read","read_file",Json.obj("path",wrong.toString(),"offset",2,"limit",1)));check(!paged.isError&&paged.text.contains("line two")&&!paged.text.contains("line one")&&!paged.text.contains("line three"),"recovered read respects offset and limit");
            record.put("status","partial");Files.writeString(job,Json.write(record));check(!read(tool,wrong).isError,"partial job can expose its confirmed existing results without claiming completion");record.put("status","done");
            Files.writeString(job,"not JSON");check(read(tool,wrong).isError&&!read(tool,wrong).text.contains("line two"),"malformed manifest stays an ordinary error");Files.writeString(job," ".repeat(1048577));check(read(tool,wrong).isError,"oversized manifest is not read");Files.writeString(job,Json.write(record));
            Path secret=Files.writeString(root.resolve("settings.properties"),"SECRET-CONTENT");Files.delete(correct);Files.createLink(correct,secret);check(read(tool,wrong).isError&&!read(tool,wrong).text.contains("SECRET-CONTENT"),"confirmed target cannot bypass protected settings through a hard link");Files.delete(correct);Files.writeString(correct,"confirmed-result");
            byte[] before=Files.readAllBytes(correct),manifest=Files.readAllBytes(job);check(!read(tool,wrong).isError&&Arrays.equals(before,Files.readAllBytes(correct))&&Arrays.equals(manifest,Files.readAllBytes(job))&&!Files.exists(wrong),"recovery is read-only and creates no aliases or folders");
            Files.delete(job);check(!read(tool,wrong).text.contains(correct.toString()),"missing manifest has ordinary missing-file result");check(!read(tool,root.resolve("ordinary-missing.json")).text.contains("pdfcontrol_job_status"),"unrelated missing file is unaffected");
            System.out.println("PASS: "+checks+" PDF result-path recovery checks; six languages, exact job evidence and access boundaries");
        }finally{I18n.setLanguage("ro");try(var paths=Files.walk(root)){for(Path p:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}
    }
}
